begin;
lock table public.clinical_guidelines in share mode;
lock table public.guideline_versions in share row exclusive mode;
create temporary table population_batch on commit drop as
select * from jsonb_to_recordset($population$[{"id":"c21a33c2-d701-4435-8ba7-e8f75db067fa","title":"Hyperosmolar Hyperglycaemic State","original_version_id":"c21a33c2-d701-4435-8ba7-e8f75db067fa","expected_hash":"9eec0b67458f167848c7824d97e0bcb3","source_url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_06_The_Management_of_Hyperosmolar_Hyperglycaemic_State_HHS_%20in_Adults_FINAL_0.pdf","source_title":"The management of the hyperosmolar hyperglycaemic state (HHS) in adults with diabetes","issuer":"Other","scope":"Adults with HHS in hospital; this limited extraction covers diagnostic features, severity assessment, early fluid and electrolyte management, fixed-rate intravenous insulin when indicated, monitoring and resolution.","content":{"id":"c21a33c2-d701-4435-8ba7-e8f75db067fa","title":"Hyperosmolar Hyperglycaemic State","specialty":"Endocrinology / Emergency Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Urgent Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Residual insulin may suppress ketogenesis while failing to prevent severe hyperglycaemia; prolonged osmotic diuresis causes profound water deficit and hyperosmolality. Infection, impaired access to fluids, medicines, and vascular illness are common contributors. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Residual insulin may suppress ketogenesis while failing to prevent severe hyperglycaemia","prolonged osmotic diuresis causes profound water deficit and hyperosmolality. Infection, impaired access to fluids, medicines, and vascular illness are common contributors."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Hyperosmolar Hyperglycaemic State, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Shock, coma, or seizures","Acute focal neurological deficit","Severe electrolyte abnormality or pulmonary oedema","Inability to protect airway or worsening consciousness"]},"differentials":[{"condition":"DKA or mixed crisis","distinguishingFeatures":"Ketonaemia and acidosis define a ketoacidotic or overlap component."},{"condition":"Stroke or intracranial haemorrhage","distinguishingFeatures":"Abrupt focal findings require emergency stroke evaluation."},{"condition":"Sepsis or medication-related delirium","distinguishingFeatures":"May precipitate HHS and independently alter cognition."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Glucose, electrolytes, renal function, ketones, venous blood gas and measured/calculated osmolality with serial neurological observations.","modalityTarget":"Glucose, electrolytes, renal function, ketones, venous blood gas and measured/calculated osmolality with serial neurological observations. — Hyperosmolar Hyperglycaemic State","targetCondition":"Hyperosmolar Hyperglycaemic State","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"specializedAdjunctive","testName":"ECG and targeted infection, stroke, cardiac, or medication evaluation.","modalityTarget":"ECG and targeted infection, stroke, cardiac, or medication evaluation. — Cause, complication, or risk relevant to Hyperosmolar Hyperglycaemic State","targetCondition":"Cause, complication, or risk relevant to Hyperosmolar Hyperglycaemic State","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Hyperosmolar Hyperglycaemic State","targetCondition":"Important alternative to Hyperosmolar Hyperglycaemic State","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[{"indication":"Fixed-rate insulin infusion for adult HHS after adequate fluid replacement when insulin is indicated","patientGroup":"Adults with HHS who have stopped responding to initial fluid replacement or have significant ketonaemia, excluding mixed DKA/HHS managed under the DKA pathway","genericName":"Soluble human insulin (Actrapid)","dose":"0.05 units/kg/hour, prepared as 50 units made up to 50 mL with 0.9% sodium chloride","route":"Intravenous infusion","frequency":"Continuous fixed-rate infusion","duration":"After adequate fluid replacement until holistic HHS resolution and safe transition from intravenous treatment","adjustments":["For mixed DKA/HHS, follow the DKA pathway using 0.1 units/kg/hour.","Delay insulin in pure HHS until adequate fluid replacement and reassessment because early insulin can cause circulatory collapse and rapid osmotic change.","When glucose is below 14 mmol/L, add 5% or 10% glucose at 125 mL/hour and continue 0.9% sodium chloride according to fluid status."],"monitoring":["Monitor glucose, calculated osmolality, sodium and potassium frequently, hourly during the initial phase.","Target glucose fall no faster than 5 mmol/L/hour and osmolality fall 3 to 8 mOsm/kg/hour.","Monitor fluid balance, cognition, haemodynamics and urine output."],"sourceTitle":"The management of the hyperosmolar hyperglycaemic state (HHS) in adults with diabetes","sourceUrl":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_06_The_Management_of_Hyperosmolar_Hyperglycaemic_State_HHS_%20in_Adults_FINAL_0.pdf","sourceEdition":"JBDS 06, February 2022; PDF pages 12 to 32 and care pathway pages 38 to 42: diagnostic criteria, fluid replacement, insulin, potassium replacement, monitoring and resolution"}],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with HHS in hospital; this limited extraction covers diagnostic features, severity assessment, early fluid and electrolyte management, fixed-rate intravenous insulin when indicated, monitoring and resolution. The guideline requires clinical judgement for frail adults, people aged 18 to 25 years, pregnancy, heart failure, renal failure and mixed DKA/HHS. The encoded insulin regimen is limited to adult HHS after adequate fluid replacement; complete medicine contraindications, local pump preparation policy and thromboprophylaxis dose are not established by this extraction. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"62e1b29d-4e5b-4d06-b394-cca4f1844d0b","title":"The management of the hyperosmolar hyperglycaemic state (HHS) in adults with diabetes","issuer":"Other","edition":"JBDS 06, February 2022","url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_06_The_Management_of_Hyperosmolar_Hyperglycaemic_State_HHS_%20in_Adults_FINAL_0.pdf","locator":"PDF pages 12 to 32 and care pathway pages 38 to 42: diagnostic criteria, fluid replacement, insulin, potassium replacement, monitoring and resolution","primary_source":true}],"selection_rationale":"Unverified scope: Adults with HHS in hospital; this limited extraction covers diagnostic features, severity assessment, early fluid and electrolyte management, fixed-rate intravenous insulin when indicated, monitoring and resolution."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"HHS diagnostic assessment","clinical_question":"Does the biochemical and clinical picture support HHS rather than DKA or another cause of hyperglycaemia?","expected_finding":"Typical HHS features are marked hypovolaemia, glucose 30 mmol/L or more, osmolality usually 320 mOsm/kg or more, ketones 3 mmol/L or less, pH 7.3 or more and bicarbonate 15 mmol/L or more.","decision_rationale":"HHS and mixed DKA/HHS require different insulin timing and rates.","timeframe":"At presentation before treatment, without delaying urgent resuscitation"},{"test":"Severity and escalation assessment","clinical_question":"Are there features requiring high-dependency or level 2 care?","expected_finding":"Escalation features include osmolality above 350 mOsm/kg, sodium above 160 mmol/L, pH below 7.1, potassium below 3.5 or above 6 mmol/L, GCS below 12, oxygen saturation below 92%, systolic pressure below 90 mmHg, pulse above 100 or below 60, urine output below 0.5 mL/kg/hour, creatinine above 200 micromol/L or acute kidney injury.","decision_rationale":"Severe biochemical or physiological disturbance predicts complications and need for closer monitoring.","timeframe":"At admission and repeatedly during early treatment"},{"test":"Serial glucose, calculated osmolality and electrolytes","clinical_question":"Are fluid and insulin therapy correcting hyperosmolality at a safe rate?","expected_finding":"Target an osmolality fall of 3 to 8 mOsm/kg/hour and a glucose fall no faster than 5 mmol/L/hour; assess sodium, potassium, renal function, fluid balance, cognition and urine output.","decision_rationale":"Rapid osmotic change and potassium disturbance can cause neurological or cardiac harm.","timeframe":"Hourly in the initial phase, then at intervals directed by response and local protocol"}],"evidence":{"sources":[{"id":"62e1b29d-4e5b-4d06-b394-cca4f1844d0b","title":"The management of the hyperosmolar hyperglycaemic state (HHS) in adults with diabetes","issuer":"Other","edition":"JBDS 06, February 2022","url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_06_The_Management_of_Hyperosmolar_Hyperglycaemic_State_HHS_%20in_Adults_FINAL_0.pdf","locator":"PDF pages 12 to 32 and care pathway pages 38 to 42: diagnostic criteria, fluid replacement, insulin, potassium replacement, monitoring and resolution","primary_source":true}],"selection_rationale":"Unverified scope: Adults with HHS in hospital; this limited extraction covers diagnostic features, severity assessment, early fluid and electrolyte management, fixed-rate intravenous insulin when indicated, monitoring and resolution."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Give 0.9% sodium chloride 1 litre intravenously over the first hour, using slower replacement when appropriate in younger adults, older or frail people, pregnancy, heart failure or renal failure; then individualise replacement against osmolality, sodium, haemodynamics and fluid balance.","timeframe":"Immediately after assessment"},{"instruction":"Do not start insulin immediately in pure HHS without significant ketonaemia; restore circulating volume first. If glucose falls below 14 mmol/L, add 5% or 10% glucose at 125 mL/hour while continuing 0.9% sodium chloride as required.","timeframe":"During initial fluid treatment and subsequent glucose fall"},{"instruction":"Use holistic resolution criteria: osmolality below 300 mOsm/kg, hypovolaemia corrected with urine output at least 0.5 mL/kg/hour, cognition returned to baseline and glucose below 15 mmol/L; complete resolution may take up to 72 hours.","timeframe":"Before transition from acute HHS treatment"},{"instruction":"Review gaps: The guideline requires clinical judgement for frail adults, people aged 18 to 25 years, pregnancy, heart failure, renal failure and mixed DKA/HHS. The encoded insulin regimen is limited to adult HHS after adequate fluid replacement; complete medicine contraindications, local pump preparation policy and thromboprophylaxis dose are not established by this extraction. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"62e1b29d-4e5b-4d06-b394-cca4f1844d0b","title":"The management of the hyperosmolar hyperglycaemic state (HHS) in adults with diabetes","issuer":"Other","edition":"JBDS 06, February 2022","url":"https://abcd.care/sites/default/files/site_uploads/JBDS_Guidelines_Current/JBDS_06_The_Management_of_Hyperosmolar_Hyperglycaemic_State_HHS_%20in_Adults_FINAL_0.pdf","locator":"PDF pages 12 to 32 and care pathway pages 38 to 42: diagnostic criteria, fluid replacement, insulin, potassium replacement, monitoring and resolution","primary_source":true}],"selection_rationale":"Unverified scope: Adults with HHS in hospital; this limited extraction covers diagnostic features, severity assessment, early fluid and electrolyte management, fixed-rate intravenous insulin when indicated, monitoring and resolution."}}]},"nonClinicalManagement":{"patientEducation":["Explain hyperosmolar hyperglycaemic state in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Endocrinology / Emergency Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"a1020000-0000-4000-8000-000000000002","title":"Hypertension in Adults [Adapted from NICE]","original_version_id":"a1020000-0000-4000-8000-000000000002","expected_hash":"051db260db8e01ffb60e6fb2f8500a71","source_url":"https://www.nice.org.uk/guidance/ng136/chapter/Recommendations","source_title":"Hypertension in adults: diagnosis and management","issuer":"NICE","scope":"Adults undergoing diagnosis, cardiovascular-risk assessment and management of primary hypertension; pregnancy and specialist secondary-hypertension pathways are outside this limited extraction.","content":{"id":"a1020000-0000-4000-8000-000000000002","title":"Hypertension in Adults [Adapted from NICE]","specialty":"Family Medicine, Internal Medicine and Cardiology","authority":"NICE","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-02-26","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Sustained arterial hypertension reflects increased systemic vascular resistance, altered sodium-volume balance and neurohormonal activation interacting with age, genetics, adiposity and environmental exposures. Chronic pressure load accelerates vascular remodelling and damages the heart, brain, kidneys, retina and peripheral arteries.","keyMechanisms":["Renin-angiotensin-aldosterone and sympathetic activation increase vascular tone and sodium retention.","Endothelial dysfunction and arterial stiffness raise systolic pressure and pulse pressure.","Renal sodium handling and pressure natriuresis reset at a higher arterial pressure.","Persistent load causes left-ventricular hypertrophy, albuminuria, retinopathy and cerebrovascular injury."]},"presentation":{"symptoms":["Usually asymptomatic and detected on screening","Headache or dizziness, which are non-specific","Symptoms of target-organ disease such as exertional chest discomfort, breathlessness or neurological episodes","Features suggesting a secondary cause, including episodic palpitations, muscle weakness or sleep apnoea"],"physicalSigns":["Repeated elevated clinic blood pressure using correct technique","Postural blood-pressure fall in older adults, diabetes or symptomatic patients","Retinal vascular change","Signs of left-ventricular hypertrophy, heart failure, peripheral vascular disease or endocrine disease"],"redFlags":["Blood pressure at or above the severe range with retinal haemorrhage/papilloedema, confusion, chest pain, acute kidney injury or heart failure","Pregnancy or possible pregnancy with severe hypertension or concerning symptoms","Acute focal neurological deficit or aortic-dissection features","Suspected catecholamine crisis or another rapidly progressive secondary cause"]},"differentials":[{"condition":"White-coat hypertension","distinguishingFeatures":"Raised clinic readings with normal validated ambulatory or home averages."},{"condition":"Masked hypertension","distinguishingFeatures":"Normal clinic readings but elevated out-of-office averages or unexplained target-organ damage."},{"condition":"Secondary hypertension","distinguishingFeatures":"Young onset, abrupt worsening, resistant disease, hypokalaemia, renal findings, endocrine features or a medicine/substance trigger."},{"condition":"Transient blood-pressure elevation","distinguishingFeatures":"Pain, anxiety, acute illness or recent stimulant exposure with normal readings after the driver resolves."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Standardised repeated clinic blood pressure","modalityTarget":"Standardised repeated clinic blood pressure — Persistent clinic hypertension","targetCondition":"Persistent clinic hypertension","expectedFinding":"Clinic blood pressure remains at or above the diagnostic threshold after repeat measurement with correct cuff and positioning.","clinicalRationale":"Technique and repetition reduce random error and identify inter-arm difference."},{"tier":"specializedAdjunctive","testName":"Ambulatory blood-pressure monitoring","modalityTarget":"Ambulatory blood-pressure monitoring — Sustained hypertension","targetCondition":"Sustained hypertension","expectedFinding":"Average waking readings meet the validated diagnostic threshold using adequate measurements.","clinicalRationale":"Preferred confirmation method for clinic readings below the severe range and distinguishes white-coat effect."},{"tier":"laboratory","testName":"Home blood-pressure monitoring","modalityTarget":"Home blood-pressure monitoring — Sustained hypertension when ABPM is unsuitable","targetCondition":"Sustained hypertension when ABPM is unsuitable","expectedFinding":"Average readings after discarding the first day meet the validated home threshold.","clinicalRationale":"Provides confirmation and supports later self-monitoring when performed with a validated device and protocol."}],"ruleOut":[{"tier":"laboratory","testName":"Urine albumin-creatinine ratio and urinalysis","modalityTarget":"Urine albumin-creatinine ratio and urinalysis — Chronic kidney disease or renal target-organ damage","targetCondition":"Chronic kidney disease or renal target-organ damage","expectedFinding":"No albuminuria or haematuria, or an abnormality prompts renal evaluation.","clinicalRationale":"Renal disease can be both a cause and consequence of hypertension and changes treatment choice and targets."},{"tier":"laboratory","testName":"Electrolytes, creatinine/eGFR, glycated haemoglobin and lipid profile","modalityTarget":"Electrolytes, creatinine/eGFR, glycated haemoglobin and lipid profile — Secondary contributor and cardiovascular comorbidity","targetCondition":"Secondary contributor and cardiovascular comorbidity","expectedFinding":"Baseline metabolic and renal status is defined; hypokalaemia, kidney dysfunction or diabetes redirects assessment.","clinicalRationale":"Supports cardiovascular-risk estimation and safe medicine selection."},{"tier":"specializedAdjunctive","testName":"Fundoscopy and 12-lead electrocardiogram","modalityTarget":"Fundoscopy and 12-lead electrocardiogram — Retinal or cardiac target-organ damage","targetCondition":"Retinal or cardiac target-organ damage","expectedFinding":"No hypertensive retinopathy or left-ventricular/cardiac abnormality, or damage is documented for risk management.","clinicalRationale":"Target-organ damage changes urgency and the balance of treatment benefit."}]},"clinicalManagement":[{"id":"measure-confirm","title":"Measure and confirm","timeframe":"At initial and confirmation visits","actions":["Use a validated, maintained device, correct cuff size, supported arm and a quiet seated setting.","Measure both arms initially and use the arm with the persistently higher reading.","Confirm clinic hypertension with ambulatory monitoring or, when unsuitable, structured home monitoring unless urgent severe hypertension requires immediate assessment."]},{"id":"urgent-severe","title":"Identify severe hypertension requiring urgent assessment","timeframe":"Same day when severe readings or symptoms are present","actions":["Assess for retinal, neurological, cardiac, aortic and renal target-organ injury.","Use emergency transfer for life-threatening symptoms or suspected acute organ injury.","Do not rapidly lower asymptomatic blood pressure outside a monitored, indication-specific protocol."],"branches":[{"condition":"Severe blood pressure with acute target-organ injury","actions":["Activate emergency specialist management and monitored intravenous therapy under the local protocol."]},{"condition":"Severe blood pressure without acute target-organ injury","actions":["Arrange urgent clinical review, confirm adherence and complete prompt organ assessment rather than routine follow-up."]}]},{"id":"risk-organs","title":"Assess cardiovascular risk and organ damage","timeframe":"During diagnostic confirmation","actions":["Obtain urine albumin-creatinine ratio, haematuria screen, glycated haemoglobin, electrolytes, creatinine/eGFR and lipids.","Perform fundoscopy and a 12-lead electrocardiogram.","Use a cardiovascular-risk tool validated or approved for local Saudi practice and assess for secondary-cause clues."]},{"id":"start-treatment","title":"Start lifestyle and pharmacological treatment","timeframe":"After confirmed diagnosis, sooner when severity or organ damage requires","actions":["Offer lifestyle intervention to every patient and discuss medicine using age, diabetes, kidney disease, pregnancy potential, frailty and cardiovascular risk.","Use generic ACE inhibitors, angiotensin-receptor blockers, calcium-channel blockers or thiazide-like diuretics in the guideline sequence when suitable and SFDA authorised.","Do not combine an ACE inhibitor with an angiotensin-receptor blocker.","Use current SFDA labelling and the local formulary for dose, contraindication and monitoring decisions; this record is not a prescribing source."]},{"id":"titrate-review","title":"Titrate and monitor","timeframe":"At defined intervals after each treatment change and at least annually once stable","actions":["Check adherence, side effects, postural symptoms and validated clinic or home readings before intensification.","Monitor kidney function and electrolytes after renin-angiotensin system blockers, diuretics or mineralocorticoid-receptor antagonists according to protocol.","Before labelling resistant hypertension, confirm out-of-office elevation, optimal tolerated triple therapy and adherence, then seek specialist input or use protocol-directed fourth-line treatment.","Individualise targets for frailty, multimorbidity and significant postural hypotension."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults undergoing diagnosis, cardiovascular-risk assessment and management of primary hypertension; pregnancy and specialist secondary-hypertension pathways are outside this limited extraction. NICE thresholds and risk tools require reconciliation with current Saudi policy and local formulary. Drug classes are named but complete dose, route, frequency, duration, interaction and contraindication sets are not supplied, so no medication regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"38760c73-5092-49dc-bd5a-56a7356d5ffb","title":"Hypertension in adults: diagnosis and management","issuer":"NICE","edition":"NG136, published 28 August 2019; updated 26 February 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/Recommendations","locator":"Recommendations 1.2.1 to 1.2.10, 1.3.1 to 1.3.3, 1.4.1 to 1.4.23 and 1.5.1 to 1.5.10","primary_source":true}],"selection_rationale":"Unverified scope: Adults undergoing diagnosis, cardiovascular-risk assessment and management of primary hypertension; pregnancy and specialist secondary-hypertension pathways are outside this limited extraction."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Clinic blood pressure followed by ABPM or HBPM","clinical_question":"Is persistent hypertension confirmed outside the clinic?","expected_finding":"For clinic blood pressure from 140/90 to 180/120 mmHg, offer ambulatory monitoring; use home monitoring if ambulatory monitoring is unsuitable. Confirm when clinic pressure is at least 140/90 and daytime ambulatory or home average is at least 135/85 mmHg.","decision_rationale":"Out-of-office measurement reduces misclassification from clinic-only readings.","timeframe":"During diagnostic confirmation"},{"test":"Target-organ damage and cardiovascular-risk assessment","clinical_question":"Has hypertension caused renal, retinal or cardiac injury and what is the person's cardiovascular risk?","expected_finding":"Assess urine albumin:creatinine ratio and haematuria, HbA1c, electrolytes, creatinine/eGFR, cholesterol, fundi and 12-lead ECG, and estimate cardiovascular risk.","decision_rationale":"Organ damage and risk influence treatment urgency and targets.","timeframe":"At confirmed diagnosis and as clinically indicated"},{"test":"Severe-hypertension emergency assessment","clinical_question":"Does blood pressure at or above 180/120 mmHg have retinal, neurological, cardiac or renal emergency features?","expected_finding":"Same-day specialist assessment is required when severe hypertension is accompanied by retinal haemorrhage or papilloedema, confusion, chest pain, heart failure or acute kidney injury.","decision_rationale":"Acute target-organ injury requires urgent specialist treatment.","timeframe":"Immediately when severe hypertension is identified"}],"evidence":{"sources":[{"id":"38760c73-5092-49dc-bd5a-56a7356d5ffb","title":"Hypertension in adults: diagnosis and management","issuer":"NICE","edition":"NG136, published 28 August 2019; updated 26 February 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/Recommendations","locator":"Recommendations 1.2.1 to 1.2.10, 1.3.1 to 1.3.3, 1.4.1 to 1.4.23 and 1.5.1 to 1.5.10","primary_source":true}],"selection_rationale":"Unverified scope: Adults undergoing diagnosis, cardiovascular-risk assessment and management of primary hypertension; pregnancy and specialist secondary-hypertension pathways are outside this limited extraction."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Set clinic targets below 140/90 mmHg for adults under 80 and below 150/90 mmHg for adults aged 80 or older, with lower corresponding home or ambulatory targets and individualisation for frailty or multimorbidity.","timeframe":"During treatment and review"},{"instruction":"Do not use an ACE inhibitor or angiotensin receptor blocker in pregnancy; use current pregnancy-specific and local prescribing guidance.","timeframe":"Before prescribing and when pregnancy is possible"},{"instruction":"Review gaps: NICE thresholds and risk tools require reconciliation with current Saudi policy and local formulary. Drug classes are named but complete dose, route, frequency, duration, interaction and contraindication sets are not supplied, so no medication regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"38760c73-5092-49dc-bd5a-56a7356d5ffb","title":"Hypertension in adults: diagnosis and management","issuer":"NICE","edition":"NG136, published 28 August 2019; updated 26 February 2026","url":"https://www.nice.org.uk/guidance/ng136/chapter/Recommendations","locator":"Recommendations 1.2.1 to 1.2.10, 1.3.1 to 1.3.3, 1.4.1 to 1.4.23 and 1.5.1 to 1.5.10","primary_source":true}],"selection_rationale":"Unverified scope: Adults undergoing diagnosis, cardiovascular-risk assessment and management of primary hypertension; pregnancy and specialist secondary-hypertension pathways are outside this limited extraction."}}]},"nonClinicalManagement":{"patientEducation":["Explain that hypertension is often silent but treatment reduces long-term cardiovascular and renal risk.","Teach validated home-monitoring technique and how to record readings without excessive repeated checking.","Discuss medicine purpose, common adverse effects, pregnancy precautions and when to seek urgent care."],"lifestyleAndDiet":["Reduce dietary sodium using culturally relevant food choices; avoid potassium-containing salt substitutes when kidney disease, diabetes or interacting medicines make them unsafe.","Encourage regular aerobic and strengthening activity and gradual weight reduction when indicated.","Limit excessive caffeine and alcohol, stop smoking and address sleep apnoea risk.","Do not recommend calcium, magnesium or potassium supplements solely to lower blood pressure."],"mdtReferrals":["Primary-care pharmacist or nurse for adherence and home-monitoring support","Nephrology, endocrinology or hypertension specialist for suspected secondary or resistant hypertension","Obstetric medicine for pregnancy, pregnancy planning or postpartum hypertension","Dietitian, weight-management and smoking-cessation services according to need"],"dischargeCriteria":["Hypertension is confirmed or excluded using an appropriate out-of-office pathway.","Target-organ and cardiovascular-risk assessment is complete or has a named owner.","Treatment, monitoring, individual target and urgent symptom advice are documented and understood."],"followUpPlan":"Review after initiation or each medicine change until a stable target is achieved, then provide at least annual review of blood pressure, postural symptoms, lifestyle, adherence, adverse effects, renal function and evolving cardiovascular risk."}}},{"id":"b3a433fb-5f23-4e19-a23f-97de51d4ef11","title":"Hypertensive Disorders of Pregnancy","original_version_id":"b3a433fb-5f23-4e19-a23f-97de51d4ef11","expected_hash":"8b8edee819c545caa99d02cbbb6507cb","source_url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations","source_title":"Hypertension in pregnancy: diagnosis and management","issuer":"NICE","scope":"Pregnant women with chronic hypertension, gestational hypertension or suspected pre-eclampsia; this limited extraction covers risk reduction, assessment, surveillance and escalation.","content":{"id":"b3a433fb-5f23-4e19-a23f-97de51d4ef11","title":"Hypertensive Disorders of Pregnancy","specialty":"Maternal-Fetal Medicine","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Safe Birth","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Abnormal placentation and maternal endothelial dysfunction can produce systemic vasoconstriction and organ injury. Disease may progress rapidly, affecting maternal brain, liver, kidney, lungs, coagulation, placenta, and fetus. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Abnormal placentation and maternal endothelial dysfunction can produce systemic vasoconstriction and organ injury. Disease may progress rapidly, affecting maternal brain, liver, kidney, lungs, coagulation, placenta, and fetus.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Hypertensive Disorders of Pregnancy, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Severe-range pressure or neurological symptoms","Right upper abdominal pain, dyspnoea, or visual disturbance","Seizure, pulmonary oedema, or reduced fetal movement","Thrombocytopenia, liver injury, or renal deterioration"]},"differentials":[{"condition":"Chronic hypertension","distinguishingFeatures":"Pre-pregnancy history and baseline testing help classify."},{"condition":"Gestational hypertension","distinguishingFeatures":"No proteinuria/severe feature at assessment, but progression risk remains."},{"condition":"Migraine or other headache cause","distinguishingFeatures":"Do not attribute new severe headache to benign cause without assessment."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Serial blood pressure, urine protein assessment, CBC/platelets, renal and liver profile; fetal growth and wellbeing assessment.","modalityTarget":"Serial blood pressure, urine protein assessment, CBC/platelets, renal and liver profile; fetal growth and wellbeing assessment. — Hypertensive Disorders of Pregnancy","targetCondition":"Hypertensive Disorders of Pregnancy","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Urgent tests and observation frequency follow local obstetric protocol.","modalityTarget":"Urgent tests and observation frequency follow local obstetric protocol. — Cause, complication, or risk relevant to Hypertensive Disorders of Pregnancy","targetCondition":"Cause, complication, or risk relevant to Hypertensive Disorders of Pregnancy","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Hypertensive Disorders of Pregnancy","targetCondition":"Important alternative to Hypertensive Disorders of Pregnancy","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Pregnant women with chronic hypertension, gestational hypertension or suspected pre-eclampsia; this limited extraction covers risk reduction, assessment, surveillance and escalation. Aspirin 75 to 150 mg daily from 12 weeks and labetalol, nifedipine or methyldopa are recommended in defined circumstances, but the source does not supply a complete route, exact regimen for all indications, interaction and contraindication set, so no medication regimen is encoded. Local obstetric emergency thresholds, formulary and fetal-surveillance protocols must be reconciled. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"ce27ba0e-f286-4215-b883-4651a70c6b07","title":"Hypertension in pregnancy: diagnosis and management","issuer":"NICE","edition":"NG133, published 25 June 2019; updated 17 April 2023","url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations","locator":"Recommendations 1.1.2, 1.2.1 to 1.2.14, 1.3.1 to 1.3.19, Tables 1 and 2, and 1.5.1 to 1.5.25","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women with chronic hypertension, gestational hypertension or suspected pre-eclampsia; this limited extraction covers risk reduction, assessment, surveillance and escalation."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Maternal blood pressure, urinalysis and laboratory assessment","clinical_question":"Is gestational hypertension or pre-eclampsia present and is maternal organ dysfunction developing?","expected_finding":"Assess blood pressure and proteinuria, and obtain full blood count, liver function and renal function according to the disorder and severity.","decision_rationale":"Maternal hypertension, proteinuria, thrombocytopenia and renal or hepatic dysfunction determine diagnosis, surveillance and escalation.","timeframe":"At presentation and repeated according to severity and specialist plan"},{"test":"Placental growth factor testing","clinical_question":"Can suspected pre-eclampsia between 20 weeks and 36 weeks plus 6 days be clarified?","expected_finding":"Offer a single placental growth factor-based test to help rule out pre-eclampsia when it is suspected in this gestational window.","decision_rationale":"Placental biomarker testing can support diagnostic triage alongside clinical assessment.","timeframe":"Once per episode of suspected pre-eclampsia in the specified gestational window"},{"test":"Ultrasound fetal growth and wellbeing assessment","clinical_question":"Is hypertension affecting fetal growth, amniotic fluid or placental circulation?","expected_finding":"Use fetal biometry, amniotic-fluid assessment and umbilical-artery Doppler according to the hypertensive disorder and gestation.","decision_rationale":"Placental dysfunction can cause fetal growth restriction and influence timing of birth.","timeframe":"At diagnosis and repeated according to the NICE tables and clinical findings"}],"evidence":{"sources":[{"id":"ce27ba0e-f286-4215-b883-4651a70c6b07","title":"Hypertension in pregnancy: diagnosis and management","issuer":"NICE","edition":"NG133, published 25 June 2019; updated 17 April 2023","url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations","locator":"Recommendations 1.1.2, 1.2.1 to 1.2.14, 1.3.1 to 1.3.19, Tables 1 and 2, and 1.5.1 to 1.5.25","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women with chronic hypertension, gestational hypertension or suspected pre-eclampsia; this limited extraction covers risk reduction, assessment, surveillance and escalation."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"For chronic hypertension in pregnancy, aim for a blood pressure target of 135/85 mmHg and arrange specialist antenatal review and surveillance.","timeframe":"Throughout pregnancy once treatment is required"},{"instruction":"Stop ACE inhibitors or angiotensin receptor blockers within 2 working days of pregnancy notification and offer an alternative suitable for pregnancy.","timeframe":"As soon as pregnancy is known"},{"instruction":"Escalate severe hypertension, maternal organ dysfunction, concerning symptoms or fetal compromise urgently to obstetric specialist care and plan timing of birth through senior multidisciplinary assessment.","timeframe":"Immediately when severe or deteriorating features occur"},{"instruction":"Review gaps: Aspirin 75 to 150 mg daily from 12 weeks and labetalol, nifedipine or methyldopa are recommended in defined circumstances, but the source does not supply a complete route, exact regimen for all indications, interaction and contraindication set, so no medication regimen is encoded. Local obstetric emergency thresholds, formulary and fetal-surveillance protocols must be reconciled. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"ce27ba0e-f286-4215-b883-4651a70c6b07","title":"Hypertension in pregnancy: diagnosis and management","issuer":"NICE","edition":"NG133, published 25 June 2019; updated 17 April 2023","url":"https://www.nice.org.uk/guidance/ng133/chapter/Recommendations","locator":"Recommendations 1.1.2, 1.2.1 to 1.2.14, 1.3.1 to 1.3.19, Tables 1 and 2, and 1.5.1 to 1.5.25","primary_source":true}],"selection_rationale":"Unverified scope: Pregnant women with chronic hypertension, gestational hypertension or suspected pre-eclampsia; this limited extraction covers risk reduction, assessment, surveillance and escalation."}}]},"nonClinicalManagement":{"patientEducation":["Explain hypertensive disorders of pregnancy in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Maternal-Fetal Medicine","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"06bb691f-eef3-4b1f-a0fc-29b94afd9254","title":"Hypothyroidism","original_version_id":"06bb691f-eef3-4b1f-a0fc-29b94afd9254","expected_hash":"a1cf450ef38cae9d5e41dab9a7247b86","source_url":"https://www.nice.org.uk/guidance/NG145/chapter/recommendations","source_title":"Thyroid disease: assessment and management","issuer":"NICE","scope":"Adults with suspected or confirmed primary hypothyroidism; this limited extraction covers biochemical testing, thyroid peroxidase antibodies, levothyroxine initiation principles and monitoring.","content":{"id":"06bb691f-eef3-4b1f-a0fc-29b94afd9254","title":"Hypothyroidism","specialty":"Endocrinology / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Reduced thyroid hormone action slows metabolic processes and can affect cardiovascular, gastrointestinal, neurological, reproductive, and lipid systems. Symptoms are nonspecific; laboratory pattern, medication exposure, pregnancy, and pituitary context shape interpretation. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Reduced thyroid hormone action slows metabolic processes and can affect cardiovascular, gastrointestinal, neurological, reproductive, and lipid systems. Symptoms are nonspecific","laboratory pattern, medication exposure, pregnancy, and pituitary context shape interpretation."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Hypothyroidism, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Altered consciousness, hypothermia, or haemodynamic instability","Pregnancy with untreated or poorly controlled disease","Possible pituitary disorder or adrenal insufficiency","Persistent symptoms despite biochemical normalisation"]},"differentials":[{"condition":"Iron deficiency or sleep disorder","distinguishingFeatures":"Common alternative contributors to fatigue."},{"condition":"Depression","distinguishingFeatures":"May coexist and needs direct assessment."},{"condition":"Central hypothyroidism","distinguishingFeatures":"Pituitary history or discordant TSH/free hormone pattern prompts specialist evaluation."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"TSH and free thyroxine interpreted with medicines, pregnancy and clinical context; assess thyroid antibodies or pituitary tests when indicated.","modalityTarget":"TSH and free thyroxine interpreted with medicines, pregnancy and clinical context; assess thyroid antibodies or pituitary tests when indicated. — Hypothyroidism","targetCondition":"Hypothyroidism","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Review lipids, cardiovascular risk, pregnancy plans and interacting supplements/medicines.","modalityTarget":"Review lipids, cardiovascular risk, pregnancy plans and interacting supplements/medicines. — Cause, complication, or risk relevant to Hypothyroidism","targetCondition":"Cause, complication, or risk relevant to Hypothyroidism","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Hypothyroidism","targetCondition":"Important alternative to Hypothyroidism","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or confirmed primary hypothyroidism; this limited extraction covers biochemical testing, thyroid peroxidase antibodies, levothyroxine initiation principles and monitoring. NICE gives levothyroxine starting doses of 1.6 micrograms/kg/day for adults under 65 without cardiovascular disease and 25 to 50 micrograms/day for adults aged 65 or older or with cardiovascular disease, but does not state a complete route, interaction and contraindication set in these recommendations, so no medication regimen is encoded. Pregnancy, severe illness, pituitary disease and paediatric care require separate pathways. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"799b9835-fd02-4902-bb92-a9fea055c82e","title":"Thyroid disease: assessment and management","issuer":"NICE","edition":"NG145, published 20 November 2019; updated 12 October 2023","url":"https://www.nice.org.uk/guidance/NG145/chapter/recommendations","locator":"Recommendations 1.2.7 to 1.2.10, 1.3.1 to 1.3.7 and 1.4.1 to 1.4.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed primary hypothyroidism; this limited extraction covers biochemical testing, thyroid peroxidase antibodies, levothyroxine initiation principles and monitoring."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"TSH with reflex free T4","clinical_question":"Does thyroid biochemistry support primary hypothyroidism?","expected_finding":"Measure TSH alone in adults when pituitary disease is not suspected, then measure free T4 in the same sample if TSH is above range; measure both TSH and free T4 when secondary thyroid dysfunction is suspected.","decision_rationale":"Test selection distinguishes primary from possible central thyroid dysfunction.","timeframe":"At initial assessment; do not repeat within 6 weeks unless clinically necessary"},{"test":"Thyroid peroxidase antibodies","clinical_question":"Is autoimmune thyroid disease a likely cause of raised TSH?","expected_finding":"Consider measuring thyroid peroxidase antibodies when TSH is above the reference range, but do not routinely repeat the test.","decision_rationale":"Autoantibody status can support aetiology and decisions in subclinical disease.","timeframe":"Once after raised TSH when clinically relevant"},{"test":"TSH monitoring after treatment","clinical_question":"Has levothyroxine normalised TSH without causing biochemical over-treatment?","expected_finding":"Measure TSH every 3 months until stable, then once a year; consider free T4 as well if symptoms persist.","decision_rationale":"Dose requirements change over time and both under-treatment and TSH suppression can cause harm.","timeframe":"Every 3 months until stable, then annually"}],"evidence":{"sources":[{"id":"799b9835-fd02-4902-bb92-a9fea055c82e","title":"Thyroid disease: assessment and management","issuer":"NICE","edition":"NG145, published 20 November 2019; updated 12 October 2023","url":"https://www.nice.org.uk/guidance/NG145/chapter/recommendations","locator":"Recommendations 1.2.7 to 1.2.10, 1.3.1 to 1.3.7 and 1.4.1 to 1.4.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed primary hypothyroidism; this limited extraction covers biochemical testing, thyroid peroxidase antibodies, levothyroxine initiation principles and monitoring."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Offer levothyroxine as first-line treatment for primary hypothyroidism and adjust to maintain TSH within the reference range while avoiding TSH suppression or thyrotoxicosis.","timeframe":"After biochemical confirmation and during follow-up"},{"instruction":"Ask about biotin supplement use because high intake can cause misleading thyroid test results; use specialist pathways when pituitary disease, pregnancy or severe illness is suspected.","timeframe":"Before interpreting thyroid tests"},{"instruction":"Review gaps: NICE gives levothyroxine starting doses of 1.6 micrograms/kg/day for adults under 65 without cardiovascular disease and 25 to 50 micrograms/day for adults aged 65 or older or with cardiovascular disease, but does not state a complete route, interaction and contraindication set in these recommendations, so no medication regimen is encoded. Pregnancy, severe illness, pituitary disease and paediatric care require separate pathways. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"799b9835-fd02-4902-bb92-a9fea055c82e","title":"Thyroid disease: assessment and management","issuer":"NICE","edition":"NG145, published 20 November 2019; updated 12 October 2023","url":"https://www.nice.org.uk/guidance/NG145/chapter/recommendations","locator":"Recommendations 1.2.7 to 1.2.10, 1.3.1 to 1.3.7 and 1.4.1 to 1.4.5","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed primary hypothyroidism; this limited extraction covers biochemical testing, thyroid peroxidase antibodies, levothyroxine initiation principles and monitoring."}}]},"nonClinicalManagement":{"patientEducation":["Explain hypothyroidism in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Endocrinology / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"fb440d70-f345-4ece-be8b-181f403de434","title":"Intrapartum Fetal Compromise","original_version_id":"fb440d70-f345-4ece-be8b-181f403de434","expected_hash":"b57db46f5ba63ed0ed92840a5bc59bc8","source_url":"https://www.nice.org.uk/guidance/ng229/chapter/Recommendations","source_title":"Fetal monitoring in labour","issuer":"NICE","scope":"Women in labour requiring fetal monitoring; this limited extraction covers risk assessment, CTG interpretation, escalation and urgent response to acute bradycardia or prolonged deceleration.","content":{"id":"fb440d70-f345-4ece-be8b-181f403de434","title":"Intrapartum Fetal Compromise","specialty":"Obstetrics / Neonatology","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Safe Birth","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Reduced uteroplacental oxygen transfer or cord compression can produce fetal heart-rate changes. Interpretation depends on baseline, variability, decelerations, contractions, maternal condition, and trend rather than a single feature. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Reduced uteroplacental oxygen transfer or cord compression can produce fetal heart-rate changes. Interpretation depends on baseline, variability, decelerations, contractions, maternal condition, and trend rather than a single feature.","Clinical expression and progression vary with baseline risk, comorbidity, treatment exposure, and access to timely care."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Intrapartum Fetal Compromise, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Prolonged bradycardia or persistent pathological tracing","Maternal hypotension, haemorrhage, or uterine rupture concern","Tachysystole with fetal changes","Failure to improve despite corrective measures"]},"differentials":[{"condition":"Maternal fever/infection","distinguishingFeatures":"May cause fetal tachycardia and compromise."},{"condition":"Fetal sleep or medication effect","distinguishingFeatures":"Can alter variability but context and duration matter."},{"condition":"Signal artifact","distinguishingFeatures":"Confirm fetal rather than maternal heart rate."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Continuous fetal heart monitoring reviewed with contraction pattern and maternal observations; assess labour progress and reversible causes.","modalityTarget":"Continuous fetal heart monitoring reviewed with contraction pattern and maternal observations; assess labour progress and reversible causes. — Intrapartum Fetal Compromise","targetCondition":"Intrapartum Fetal Compromise","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Use locally adopted fetal monitoring classification and escalation timeframes.","modalityTarget":"Use locally adopted fetal monitoring classification and escalation timeframes. — Cause, complication, or risk relevant to Intrapartum Fetal Compromise","targetCondition":"Cause, complication, or risk relevant to Intrapartum Fetal Compromise","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Intrapartum Fetal Compromise","targetCondition":"Important alternative to Intrapartum Fetal Compromise","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Women in labour requiring fetal monitoring; this limited extraction covers risk assessment, CTG interpretation, escalation and urgent response to acute bradycardia or prolonged deceleration. CTG interpretation must be integrated with the whole clinical picture, gestation and local obstetric escalation policy. The source names measures such as stopping oxytocin but does not provide a complete medication regimen or contraindication set, so no medicine regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"a942bbd0-e0c5-43cc-ab0d-3fc056a82845","title":"Fetal monitoring in labour","issuer":"NICE","edition":"NG229, published 14 December 2022; updated 25 March 2026","url":"https://www.nice.org.uk/guidance/ng229/chapter/Recommendations","locator":"Recommendations 1.3.1 to 1.3.12, 1.4.3 to 1.4.38, Tables 1 to 3 and 1.5.1 to 1.5.11","primary_source":true}],"selection_rationale":"Unverified scope: Women in labour requiring fetal monitoring; this limited extraction covers risk assessment, CTG interpretation, escalation and urgent response to acute bradycardia or prolonged deceleration."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Hourly intrapartum risk assessment","clinical_question":"Have maternal, fetal or labour risk factors emerged that require continuous CTG or escalation?","expected_finding":"Perform and document a systematic assessment at least hourly and use a second clinician for a fresh-eyes review of continuous CTG at least hourly.","decision_rationale":"Risk and fetal response can change rapidly during labour.","timeframe":"At least hourly during labour"},{"test":"Structured CTG feature assessment","clinical_question":"How should contractions, baseline rate, variability and decelerations be classified?","expected_finding":"Classify each CTG feature using the white, amber and red criteria and combine the features with the clinical context to describe the trace as normal, suspicious or pathological.","decision_rationale":"A common structured vocabulary supports consistent escalation and response.","timeframe":"Continuously, with formal documented review at least hourly"},{"test":"Acute bradycardia or prolonged deceleration assessment","clinical_question":"Has fetal heart rate fallen acutely for 3 minutes or longer?","expected_finding":"An acute bradycardia or a single prolonged deceleration lasting 3 minutes or more requires urgent obstetric review and preparation for urgent birth.","decision_rationale":"Persistent acute heart-rate reduction may indicate rapidly developing fetal hypoxia.","timeframe":"Immediate recognition and response"}],"evidence":{"sources":[{"id":"a942bbd0-e0c5-43cc-ab0d-3fc056a82845","title":"Fetal monitoring in labour","issuer":"NICE","edition":"NG229, published 14 December 2022; updated 25 March 2026","url":"https://www.nice.org.uk/guidance/ng229/chapter/Recommendations","locator":"Recommendations 1.3.1 to 1.3.12, 1.4.3 to 1.4.38, Tables 1 to 3 and 1.5.1 to 1.5.11","primary_source":true}],"selection_rationale":"Unverified scope: Women in labour requiring fetal monitoring; this limited extraction covers risk assessment, CTG interpretation, escalation and urgent response to acute bradycardia or prolonged deceleration."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"For a suspicious or pathological CTG, undertake urgent review of reversible causes and the whole clinical picture, escalate according to severity and document the plan and review interval.","timeframe":"Immediately after abnormal classification"},{"instruction":"For acute bradycardia or prolonged deceleration lasting 3 minutes or more, call for urgent obstetric help, prepare for urgent birth and expedite birth if recovery is inadequate or other risk factors persist.","timeframe":"Immediately"},{"instruction":"When CTG concerns arise in active second stage, consider stopping oxytocin and discourage pushing unless birth is imminent while urgent senior review proceeds.","timeframe":"During active second stage when concerns occur"},{"instruction":"Review gaps: CTG interpretation must be integrated with the whole clinical picture, gestation and local obstetric escalation policy. The source names measures such as stopping oxytocin but does not provide a complete medication regimen or contraindication set, so no medicine regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"a942bbd0-e0c5-43cc-ab0d-3fc056a82845","title":"Fetal monitoring in labour","issuer":"NICE","edition":"NG229, published 14 December 2022; updated 25 March 2026","url":"https://www.nice.org.uk/guidance/ng229/chapter/Recommendations","locator":"Recommendations 1.3.1 to 1.3.12, 1.4.3 to 1.4.38, Tables 1 to 3 and 1.5.1 to 1.5.11","primary_source":true}],"selection_rationale":"Unverified scope: Women in labour requiring fetal monitoring; this limited extraction covers risk assessment, CTG interpretation, escalation and urgent response to acute bradycardia or prolonged deceleration."}}]},"nonClinicalManagement":{"patientEducation":["Explain intrapartum fetal compromise in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Obstetrics / Neonatology","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"c1e45d3f-fa28-49f1-ab69-3ee4ab9cac6f","title":"Ischaemic Heart Disease","original_version_id":"c1e45d3f-fa28-49f1-ab69-3ee4ab9cac6f","expected_hash":"e2e7f187d056e153f06a0c2ae2dd92d9","source_url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","source_title":"Stable angina: management","issuer":"NICE","scope":"Adults with stable angina due to atherosclerotic coronary disease; this limited extraction covers symptom review, secondary prevention, antianginal treatment principles and revascularisation assessment.","content":{"id":"c1e45d3f-fa28-49f1-ab69-3ee4ab9cac6f","title":"Ischaemic Heart Disease","specialty":"Cardiology / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Chronic Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Atherosclerotic plaque and endothelial dysfunction limit coronary flow. Plaque disruption can cause acute thrombosis and myocardial injury; secondary prevention reduces future vascular events. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Atherosclerotic plaque and endothelial dysfunction limit coronary flow. Plaque disruption can cause acute thrombosis and myocardial injury","secondary prevention reduces future vascular events."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Ischaemic Heart Disease, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["New rest pain or crescendo symptoms","Syncope, acute dyspnoea, or haemodynamic instability","New neurological deficit","Persistent symptoms despite treatment"]},"differentials":[{"condition":"Gastro-oesophageal disease","distinguishingFeatures":"Meal/position relation may help but does not exclude cardiac cause."},{"condition":"Musculoskeletal pain","distinguishingFeatures":"Reproducibility may support another cause but is not definitive."},{"condition":"Pulmonary disease or anxiety","distinguishingFeatures":"May coexist; assess risk and objective findings."}],"investigations":{"ruleIn":[{"tier":"specializedAdjunctive","testName":"ECG and risk-based cardiac evaluation; blood pressure, lipids, glycaemia, renal function and heart-failure assessment as indicated.","modalityTarget":"ECG and risk-based cardiac evaluation; blood pressure, lipids, glycaemia, renal function and heart-failure assessment as indicated. — Ischaemic Heart Disease","targetCondition":"Ischaemic Heart Disease","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Medication reconciliation and adverse-effect assessment are central to risk reduction.","modalityTarget":"Medication reconciliation and adverse-effect assessment are central to risk reduction. — Cause, complication, or risk relevant to Ischaemic Heart Disease","targetCondition":"Cause, complication, or risk relevant to Ischaemic Heart Disease","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Ischaemic Heart Disease","targetCondition":"Important alternative to Ischaemic Heart Disease","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with stable angina due to atherosclerotic coronary disease; this limited extraction covers symptom review, secondary prevention, antianginal treatment principles and revascularisation assessment. This older UK guideline must be reconciled with current ESC, ACC/AHA and Saudi guidance, contemporary chronic-coronary-syndrome diagnostics, lipid targets, antiplatelet practice and revascularisation evidence. Aspirin 75 mg daily and short-acting nitrates are mentioned, but the source does not provide complete route, duration, interaction and contraindication sets, so no medication regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"d171d279-5878-47ad-9e58-f9cd129cc18d","title":"Stable angina: management","issuer":"NICE","edition":"CG126, published 23 July 2011; updated 25 August 2016","url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","locator":"Recommendations 1.2.1 to 1.2.6, 1.3.1 to 1.3.19 and 1.5.1 to 1.5.14","primary_source":true}],"selection_rationale":"Unverified scope: Adults with stable angina due to atherosclerotic coronary disease; this limited extraction covers symptom review, secondary prevention, antianginal treatment principles and revascularisation assessment."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Stable-angina symptom and functional review","clinical_question":"Are symptoms consistent with stable angina and are frequency, triggers and functional impact changing?","expected_finding":"Review the diagnosis, symptom burden, adherence, adverse effects and modifiable risk factors when starting or adjusting treatment.","decision_rationale":"Worsening or atypical symptoms can require a different acute or diagnostic pathway.","timeframe":"At presentation and 2 to 4 weeks after starting or changing treatment"},{"test":"Coronary anatomy and functional assessment when symptoms persist","clinical_question":"Would angiography and functional testing alter revascularisation decisions?","expected_finding":"When symptoms are not satisfactorily controlled with optimal medical treatment, offer coronary angiography to guide treatment and use additional functional testing if required.","decision_rationale":"Anatomy, ischaemia and clinical factors determine whether CABG, PCI or continued medical therapy is appropriate.","timeframe":"After inadequate symptom control or when prognostic anatomy is suspected"},{"test":"Multidisciplinary revascularisation assessment","clinical_question":"Do anatomy, diabetes, age, comorbidity and procedural suitability favour CABG, PCI or continued medical care?","expected_finding":"Complex left-main or three-vessel disease and uncertain strategy should be reviewed by cardiac surgeons and interventional cardiologists.","decision_rationale":"Balanced specialist review supports informed selection of the revascularisation strategy.","timeframe":"Before elective revascularisation"}],"evidence":{"sources":[{"id":"d171d279-5878-47ad-9e58-f9cd129cc18d","title":"Stable angina: management","issuer":"NICE","edition":"CG126, published 23 July 2011; updated 25 August 2016","url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","locator":"Recommendations 1.2.1 to 1.2.6, 1.3.1 to 1.3.19 and 1.5.1 to 1.5.14","primary_source":true}],"selection_rationale":"Unverified scope: Adults with stable angina due to atherosclerotic coronary disease; this limited extraction covers symptom review, secondary prevention, antianginal treatment principles and revascularisation assessment."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Provide a short-acting nitrate for angina episodes and explain that the dose may be repeated after 5 minutes; call an emergency ambulance if pain persists 5 minutes after the second dose.","timeframe":"At diagnosis and reinforced at review"},{"instruction":"Offer a beta blocker or calcium-channel blocker as first-line regular antianginal treatment, selected according to comorbidity, contraindications and preference, and review response 2 to 4 weeks after starting or changing therapy.","timeframe":"During symptom management"},{"instruction":"Discuss revascularisation when symptoms remain uncontrolled despite optimal treatment, using shared decisions on symptom relief, procedure risks, repeat intervention and possible prognostic benefit.","timeframe":"After inadequate control with medical treatment"},{"instruction":"Review gaps: This older UK guideline must be reconciled with current ESC, ACC/AHA and Saudi guidance, contemporary chronic-coronary-syndrome diagnostics, lipid targets, antiplatelet practice and revascularisation evidence. Aspirin 75 mg daily and short-acting nitrates are mentioned, but the source does not provide complete route, duration, interaction and contraindication sets, so no medication regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"d171d279-5878-47ad-9e58-f9cd129cc18d","title":"Stable angina: management","issuer":"NICE","edition":"CG126, published 23 July 2011; updated 25 August 2016","url":"https://www.nice.org.uk/guidance/cg126/chapter/Recommendations","locator":"Recommendations 1.2.1 to 1.2.6, 1.3.1 to 1.3.19 and 1.5.1 to 1.5.14","primary_source":true}],"selection_rationale":"Unverified scope: Adults with stable angina due to atherosclerotic coronary disease; this limited extraction covers symptom review, secondary prevention, antianginal treatment principles and revascularisation assessment."}}]},"nonClinicalManagement":{"patientEducation":["Explain ischaemic heart disease in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Cardiology / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"2886cf83-6050-45de-a152-ea9bced0afb7","title":"Kidney Failure Planning and Dialysis Access","original_version_id":"2886cf83-6050-45de-a152-ea9bced0afb7","expected_hash":"37c1588c0e57c250bf50d874b2e36293","source_url":"https://www.nice.org.uk/guidance/ng107/chapter/Recommendations","source_title":"Renal replacement therapy and conservative management","issuer":"NICE","scope":"Adults approaching kidney failure who are choosing between conservative care and renal replacement therapy; this limited extraction covers shared decisions, timing of dialysis and access planning.","content":{"id":"2886cf83-6050-45de-a152-ea9bced0afb7","title":"Kidney Failure Planning and Dialysis Access","specialty":"Nephrology / Vascular Surgery","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Progressive nephron loss may lead to fluid, electrolyte, and uraemic complications. Preparation before kidney failure allows informed modality choice and planned access; the best pathway depends on health, support, geography, and preferences. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Progressive nephron loss may lead to fluid, electrolyte, and uraemic complications. Preparation before kidney failure allows informed modality choice and planned access","the best pathway depends on health, support, geography, and preferences."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Kidney Failure Planning and Dialysis Access, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Rapid decline or refractory metabolic/fluid complication","Acute uraemic symptoms or pericarditis","Access infection, thrombosis, or limb ischaemia","Severe distress or decisional conflict"]},"differentials":[{"condition":"AKI on CKD","distinguishingFeatures":"Abrupt decline may be reversible and alter timing."},{"condition":"Obstructive nephropathy","distinguishingFeatures":"May be treatable before irreversible progression."},{"condition":"Conservative kidney care preference","distinguishingFeatures":"A valid active pathway, not absence of care."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Trend eGFR and albuminuria, kidney failure risk, potassium/acid-base status, anaemia and mineral-bone profile.","modalityTarget":"Trend eGFR and albuminuria, kidney failure risk, potassium/acid-base status, anaemia and mineral-bone profile. — Kidney Failure Planning and Dialysis Access","targetCondition":"Kidney Failure Planning and Dialysis Access","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Vascular mapping, transplant evaluation and modality testing follow local service criteria and patient choice.","modalityTarget":"Vascular mapping, transplant evaluation and modality testing follow local service criteria and patient choice. — Cause, complication, or risk relevant to Kidney Failure Planning and Dialysis Access","targetCondition":"Cause, complication, or risk relevant to Kidney Failure Planning and Dialysis Access","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Kidney Failure Planning and Dialysis Access","targetCondition":"Important alternative to Kidney Failure Planning and Dialysis Access","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults approaching kidney failure who are choosing between conservative care and renal replacement therapy; this limited extraction covers shared decisions, timing of dialysis and access planning. This 2018 UK guideline requires reconciliation with current Saudi nephrology policy, transplant pathways, vascular mapping standards, access-service capacity and updated evidence. It does not verify anticoagulation, antimicrobial, anaemia, mineral-bone or dialysis prescription regimens. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"4cfb7b13-2f9b-4a8a-9d61-364ead57acb0","title":"Renal replacement therapy and conservative management","issuer":"NICE","edition":"NG107, published 3 October 2018","url":"https://www.nice.org.uk/guidance/ng107/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.9, 1.2.1 to 1.2.6, 1.3.1 to 1.3.7 and 1.5.1 to 1.5.8","primary_source":true}],"selection_rationale":"Unverified scope: Adults approaching kidney failure who are choosing between conservative care and renal replacement therapy; this limited extraction covers shared decisions, timing of dialysis and access planning."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Kidney-failure trajectory and symptom assessment","clinical_question":"When is kidney replacement therapy likely to be needed and are symptoms or biochemical abnormalities becoming refractory?","expected_finding":"Assess symptoms, biochemical measures, fluid status and eGFR together; dialysis may be needed for symptoms, uncontrolled biochemistry or fluid overload, or at eGFR around 5 to 7 mL/min/1.73 m² if no symptoms are present.","decision_rationale":"Dialysis initiation should reflect clinical need rather than an isolated eGFR value.","timeframe":"Repeated during advanced chronic kidney disease and before planned initiation"},{"test":"Modality and conservative-care assessment","clinical_question":"Which option best fits prognosis, comorbidity, lifestyle, preferences and support?","expected_finding":"Discuss haemodialysis, peritoneal dialysis, transplantation and conservative management using individual clinical and personal factors.","decision_rationale":"The preferred treatment depends on benefits, burdens, feasibility and the person's goals.","timeframe":"Start assessment at least 1 year before renal replacement therapy is likely"},{"test":"Dialysis access and vascular assessment","clinical_question":"Which access type and site can be created in time for the chosen modality?","expected_finding":"Use vascular assessment including ultrasound when needed to plan an arteriovenous fistula, and assess the abdomen and practical suitability for peritoneal access.","decision_rationale":"Early planning reduces unplanned catheter-dependent dialysis and failed access.","timeframe":"Plan arteriovenous fistula creation about 6 months before expected dialysis; insert an open surgical peritoneal catheter about 2 weeks before anticipated use"}],"evidence":{"sources":[{"id":"4cfb7b13-2f9b-4a8a-9d61-364ead57acb0","title":"Renal replacement therapy and conservative management","issuer":"NICE","edition":"NG107, published 3 October 2018","url":"https://www.nice.org.uk/guidance/ng107/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.9, 1.2.1 to 1.2.6, 1.3.1 to 1.3.7 and 1.5.1 to 1.5.8","primary_source":true}],"selection_rationale":"Unverified scope: Adults approaching kidney failure who are choosing between conservative care and renal replacement therapy; this limited extraction covers shared decisions, timing of dialysis and access planning."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Begin assessment for renal replacement therapy or conservative management at least 1 year before therapy is likely to be needed, including transplant assessment when appropriate.","timeframe":"During advanced chronic kidney disease"},{"instruction":"Base dialysis initiation on symptoms, biochemical measures, uncontrollable fluid overload and estimated GFR together, through a joint decision with the person and clinical team.","timeframe":"When kidney failure is approaching or complications become refractory"},{"instruction":"Review gaps: This 2018 UK guideline requires reconciliation with current Saudi nephrology policy, transplant pathways, vascular mapping standards, access-service capacity and updated evidence. It does not verify anticoagulation, antimicrobial, anaemia, mineral-bone or dialysis prescription regimens. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"4cfb7b13-2f9b-4a8a-9d61-364ead57acb0","title":"Renal replacement therapy and conservative management","issuer":"NICE","edition":"NG107, published 3 October 2018","url":"https://www.nice.org.uk/guidance/ng107/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.9, 1.2.1 to 1.2.6, 1.3.1 to 1.3.7 and 1.5.1 to 1.5.8","primary_source":true}],"selection_rationale":"Unverified scope: Adults approaching kidney failure who are choosing between conservative care and renal replacement therapy; this limited extraction covers shared decisions, timing of dialysis and access planning."}}]},"nonClinicalManagement":{"patientEducation":["Explain kidney failure planning and dialysis access in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Nephrology / Vascular Surgery","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"92061bb4-c2ee-4146-bd7f-b8b6ffc79a54","title":"Last Days of Life Care","original_version_id":"92061bb4-c2ee-4146-bd7f-b8b6ffc79a54","expected_hash":"1a72ea2c9dd0f2b7737d8bf6d4612f6b","source_url":"https://www.nice.org.uk/guidance/ng31/chapter/Recommendations","source_title":"Care of dying adults in the last days of life","issuer":"NICE","scope":"Adults thought to be entering the last days of life; this limited extraction covers recognition of dying, individualised care planning, hydration, medicine review and symptom reassessment.","content":{"id":"92061bb4-c2ee-4146-bd7f-b8b6ffc79a54","title":"Last Days of Life Care","specialty":"Palliative Medicine / Primary Care","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Physiological decline near death may involve reduced intake, consciousness, mobility, and organ function. These changes can be distressing but vary; clear communication and repeated symptom review support comfort and family understanding. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Physiological decline near death may involve reduced intake, consciousness, mobility, and organ function. These changes can be distressing but vary","clear communication and repeated symptom review support comfort and family understanding."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Last Days of Life Care, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Uncontrolled pain, dyspnoea, seizure, or major bleeding","Potentially reversible cause consistent with expressed goals","Medication toxicity or distressing secretions","Family distress, conflict, or lack of support"]},"differentials":[{"condition":"Delirium or infection","distinguishingFeatures":"Assess reversible causes proportionately."},{"condition":"Medication toxicity","distinguishingFeatures":"Review recent changes and renal function."},{"condition":"Depression or fatigue","distinguishingFeatures":"May contribute but does not alone establish dying."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Clinical trajectory, symptom and medication review, hydration/oral care, capacity and family understanding.","modalityTarget":"Clinical trajectory, symptom and medication review, hydration/oral care, capacity and family understanding. — Last Days of Life Care","targetCondition":"Last Days of Life Care","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"laboratory","testName":"Investigate only if results will alter goal-concordant management.","modalityTarget":"Investigate only if results will alter goal-concordant management. — Cause, complication, or risk relevant to Last Days of Life Care","targetCondition":"Cause, complication, or risk relevant to Last Days of Life Care","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Last Days of Life Care","targetCondition":"Important alternative to Last Days of Life Care","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults thought to be entering the last days of life; this limited extraction covers recognition of dying, individualised care planning, hydration, medicine review and symptom reassessment. This UK guideline requires reconciliation with current Saudi law, local goals-of-care processes, family communication, spiritual care, specialist palliative services and medication protocols. It recommends symptom treatment but does not provide complete medicine dose, route, frequency, duration and contraindication sets, so no regimen is encoded. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"fef03559-65cb-4e7e-ae35-2b274daca70e","title":"Care of dying adults in the last days of life","issuer":"NICE","edition":"NG31, published 16 December 2015","url":"https://www.nice.org.uk/guidance/ng31/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.13, 1.2.1 to 1.2.5, 1.3.1 to 1.3.15 and 1.5.1 to 1.5.20","primary_source":true}],"selection_rationale":"Unverified scope: Adults thought to be entering the last days of life; this limited extraction covers recognition of dying, individualised care planning, hydration, medicine review and symptom reassessment."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Recognition-of-dying assessment","clinical_question":"Is the person likely to be entering the last days of life, recovering, or clinically uncertain?","expected_finding":"Assess changes in function, consciousness, breathing, intake, circulation and other clinical signs, seek reversible causes and communicate uncertainty when prognosis is unclear.","decision_rationale":"Care should respond to the person's condition without making an unsupported prognostic assumption.","timeframe":"At suspected entry into the last days and whenever the condition changes"},{"test":"Individualised symptom and goals assessment","clinical_question":"Which physical, psychological, social, spiritual and communication needs matter now?","expected_finding":"Create and update an individualised care plan covering goals, preferences, symptom control, hydration, current medicines and preferred place of care.","decision_rationale":"Priorities and treatment burdens differ between people and can change rapidly.","timeframe":"At least daily and after any material clinical change"},{"test":"Hydration and clinically assisted hydration review","clinical_question":"Is dehydration causing distress, can oral intake help, and is assisted hydration benefiting or harming the person?","expected_finding":"Assess hydration daily, support drinking if desired and safe, and consider a therapeutic trial of clinically assisted hydration when distressing symptoms may relate to dehydration and oral intake is inadequate.","decision_rationale":"Hydration may relieve symptoms but can also cause fluid overload or other harm.","timeframe":"Review at least daily; monitor an assisted-hydration trial at least every 12 hours"}],"evidence":{"sources":[{"id":"fef03559-65cb-4e7e-ae35-2b274daca70e","title":"Care of dying adults in the last days of life","issuer":"NICE","edition":"NG31, published 16 December 2015","url":"https://www.nice.org.uk/guidance/ng31/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.13, 1.2.1 to 1.2.5, 1.3.1 to 1.3.15 and 1.5.1 to 1.5.20","primary_source":true}],"selection_rationale":"Unverified scope: Adults thought to be entering the last days of life; this limited extraction covers recognition of dying, individualised care planning, hydration, medicine review and symptom reassessment."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Review all current medicines and stop those that are not providing symptomatic benefit or may cause harm; avoid investigations unlikely to affect care in the last days of life.","timeframe":"At recognition and daily review"},{"instruction":"Use the least invasive suitable route for symptom medicines, avoid intramuscular injections, and consider subcutaneous or intravenous delivery when oral medicines are unsuitable; consider a syringe pump if more than 2 or 3 as-needed doses are required in 24 hours.","timeframe":"During symptom management"},{"instruction":"Use the lowest effective symptom-relief dose, reassess at least daily, seek specialist palliative advice when symptoms do not improve promptly, and reduce or stop clinically assisted hydration if harm occurs.","timeframe":"Daily and after each treatment change"},{"instruction":"Review gaps: This UK guideline requires reconciliation with current Saudi law, local goals-of-care processes, family communication, spiritual care, specialist palliative services and medication protocols. It recommends symptom treatment but does not provide complete medicine dose, route, frequency, duration and contraindication sets, so no regimen is encoded. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"fef03559-65cb-4e7e-ae35-2b274daca70e","title":"Care of dying adults in the last days of life","issuer":"NICE","edition":"NG31, published 16 December 2015","url":"https://www.nice.org.uk/guidance/ng31/chapter/Recommendations","locator":"Recommendations 1.1.1 to 1.1.13, 1.2.1 to 1.2.5, 1.3.1 to 1.3.15 and 1.5.1 to 1.5.20","primary_source":true}],"selection_rationale":"Unverified scope: Adults thought to be entering the last days of life; this limited extraction covers recognition of dying, individualised care planning, hydration, medicine review and symptom reassessment."}}]},"nonClinicalManagement":{"patientEducation":["Explain last days of life care in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Palliative Medicine / Primary Care","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}},{"id":"a1010000-0000-4000-8000-000000000007","title":"Lung Cancer Management","original_version_id":"a1010000-0000-4000-8000-000000000007","expected_hash":"c824e2697a3bac808bd095503d3c840e","source_url":"https://www.nice.org.uk/guidance/ng122/chapter/Diagnosis-and-staging","source_title":"Lung cancer: diagnosis and management","issuer":"NICE","scope":"Adults with suspected or confirmed lung cancer; this limited extraction covers diagnostic imaging, tissue acquisition, molecular-pathology adequacy and staging before treatment selection.","content":{"id":"a1010000-0000-4000-8000-000000000007","title":"Lung Cancer Management","specialty":"Thoracic Oncology, Respiratory Medicine and Thoracic Surgery","authority":"SHC","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2019-01-01","pillar":"Planned Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Lung cancer arises from malignant transformation of respiratory epithelium and is broadly classified as non-small-cell or small-cell carcinoma. Local invasion, lymphatic spread and early haematogenous dissemination determine resectability and systemic treatment; molecular drivers and immune phenotype increasingly guide therapy.","keyMechanisms":["Tobacco smoke, environmental and occupational carcinogens produce cumulative genomic injury.","Histological subtype and molecular alterations determine growth pattern and treatment sensitivity.","Mediastinal nodal involvement strongly affects stage and curative options.","Metastatic spread commonly affects brain, bone, liver and adrenal glands; paraneoplastic syndromes may precede local symptoms."]},"presentation":{"symptoms":["Persistent or changing cough","Haemoptysis, breathlessness or chest pain","Unexplained weight loss, fatigue or recurrent focal pneumonia","Hoarseness, bone pain, headache or focal neurological symptoms"],"physicalSigns":["Focal reduced air entry, wheeze or signs of pleural effusion","Supraclavicular lymphadenopathy","Clubbing or features of superior vena cava obstruction","Neurological deficit, bony tenderness or paraneoplastic manifestations"],"redFlags":["Massive haemoptysis or threatened airway","Superior vena cava obstruction with respiratory or neurological compromise","Spinal-cord compression symptoms or new focal neurological deficit","Severe hypercalcaemia, pericardial tamponade or rapidly worsening respiratory failure"]},"differentials":[{"condition":"Pulmonary tuberculosis","distinguishingFeatures":"Epidemiologic risk, constitutional symptoms, cavitation and specific microbiological evidence."},{"condition":"Non-resolving pneumonia","distinguishingFeatures":"Acute infective presentation that resolves radiographically; persistence or recurrence in one lobe raises concern for obstruction."},{"condition":"Benign pulmonary nodule","distinguishingFeatures":"Stable interval imaging or benign calcification/morphology within a validated nodule pathway."},{"condition":"Metastasis from another primary tumour","distinguishingFeatures":"Known extrathoracic cancer and pathology/immunophenotype inconsistent with a pulmonary primary."}],"investigations":{"ruleIn":[{"tier":"advancedImaging","testName":"Contrast-enhanced CT chest and upper abdomen","modalityTarget":"Contrast-enhanced CT chest and upper abdomen — Primary lung malignancy and anatomical stage","targetCondition":"Primary lung malignancy and anatomical stage","expectedFinding":"Suspicious pulmonary lesion with local, nodal or metastatic features.","clinicalRationale":"Defines the safest highest-yield biopsy target and initial resectability assessment."},{"tier":"specializedAdjunctive","testName":"Image-guided, bronchoscopic or endobronchial-ultrasound biopsy","modalityTarget":"Image-guided, bronchoscopic or endobronchial-ultrasound biopsy — Histological lung-cancer diagnosis","targetCondition":"Histological lung-cancer diagnosis","expectedFinding":"Adequate tissue confirms histology and supports molecular and immune biomarker testing.","clinicalRationale":"Tissue method should maximise diagnostic and staging value while minimising procedural risk."},{"tier":"advancedImaging","testName":"PET-CT and brain imaging when stage appropriate","modalityTarget":"PET-CT and brain imaging when stage appropriate — Occult nodal or distant metastasis","targetCondition":"Occult nodal or distant metastasis","expectedFinding":"Metabolically or anatomically suspicious disease requiring confirmation when it changes curative intent.","clinicalRationale":"Prevents futile local treatment and guides invasive staging."}],"ruleOut":[{"tier":"laboratory","testName":"Microbiology on appropriate respiratory specimens","modalityTarget":"Microbiology on appropriate respiratory specimens — Tuberculosis or fungal infection","targetCondition":"Tuberculosis or fungal infection","expectedFinding":"No microbiological evidence of an infectious mimic, or infection is identified for treatment and isolation measures.","clinicalRationale":"Infection can mimic malignancy and is especially important in cavitary disease."},{"tier":"laboratory","testName":"Interval nodule imaging within a validated pathway","modalityTarget":"Interval nodule imaging within a validated pathway — Benign or indolent pulmonary nodule","targetCondition":"Benign or indolent pulmonary nodule","expectedFinding":"Long-term stability or benign evolution lowers malignancy probability.","clinicalRationale":"Avoids invasive testing for appropriately selected low-risk nodules while preserving surveillance safety."}]},"clinicalManagement":[{"id":"diagnose","title":"Obtain diagnosis and full stage","timeframe":"Urgently after suspicious imaging","actions":["Choose a biopsy that provides diagnosis and the greatest staging information with acceptable risk.","Complete TNM staging and document performance status, pulmonary function and comorbidity.","Obtain adequate tissue for current molecular-driver and immune biomarker testing in eligible non-small-cell disease."]},{"id":"thoracic-mdt","title":"Agree treatment in thoracic MDT","timeframe":"After staging and biomarker work-up","actions":["Include respiratory medicine, thoracic surgery, medical oncology, radiation oncology, radiology, pathology and supportive care.","State whether intent is curative, disease controlling or symptom focused.","Discuss clinical trials and the patient's informed preferences."]},{"id":"early-stage","title":"Treat localised disease","timeframe":"Without avoidable delay","actions":["Offer anatomical surgical resection with nodal evaluation to operable patients when oncologically appropriate.","Use definitive stereotactic or conventional radiotherapy for selected medically inoperable localised disease.","Consider peri-operative systemic therapy according to stage, histology, biomarkers and the current protocol."]},{"id":"locally-advanced","title":"Treat locally advanced disease","timeframe":"According to MDT sequence","actions":["Assess suitability for combined-modality chemoradiotherapy or selected surgical pathways.","Use generic systemic agents and radiotherapy schedules only from the current approved oncology protocol.","Monitor pulmonary, oesophageal, haematological and immune-related toxicity."]},{"id":"advanced","title":"Treat advanced disease and complications","timeframe":"Promptly after biomarker results; immediately for oncological emergencies","actions":["Select targeted therapy, immunotherapy or cytotoxic chemotherapy according to histology, molecular findings, immune phenotype and fitness.","Use palliative radiotherapy, pleural procedures, analgesia and other symptom-directed interventions early.","Escalate cord compression, major haemoptysis, severe hypercalcaemia and superior vena cava obstruction through emergency oncology pathways."]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with suspected or confirmed lung cancer; this limited extraction covers diagnostic imaging, tissue acquisition, molecular-pathology adequacy and staging before treatment selection. The NICE staging recommendations cite AJCC TNM seventh edition and therefore require reconciliation with the current TNM edition, Saudi oncology standards and local multidisciplinary pathways. This extraction does not verify surgery, radiotherapy or systemic anticancer drug regimens. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"360ba064-3f7b-4ec4-9948-1aa6fcde66b7","title":"Lung cancer: diagnosis and management","issuer":"NICE","edition":"NG122, published 28 March 2019; updated 8 March 2024","url":"https://www.nice.org.uk/guidance/ng122/chapter/Diagnosis-and-staging","locator":"Diagnosis and staging recommendations 1.2.1 to 1.2.27, including CT, tissue sampling, PET-CT and mediastinal staging","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed lung cancer; this limited extraction covers diagnostic imaging, tissue acquisition, molecular-pathology adequacy and staging before treatment selection."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Contrast-enhanced CT of chest and upper abdomen","clinical_question":"What is the likely primary tumour extent and are nodal, liver or adrenal metastases visible?","expected_finding":"Perform contrast-enhanced CT including the liver, adrenal glands and lower neck before biopsy when possible, with caution in renal impairment.","decision_rationale":"Early staging information guides the safest biopsy target and avoids tests that will not alter treatment.","timeframe":"Before tissue sampling when clinically feasible"},{"test":"Tissue diagnosis with subtype and molecular-marker adequacy","clinical_question":"Can the selected procedure provide enough material for diagnosis, histological subtype and relevant molecular testing?","expected_finding":"Choose investigations that give the most information about diagnosis and stage with the least risk, and obtain samples adequate for pathological subtyping and molecular-marker testing.","decision_rationale":"Treatment selection depends on accurate histology, stage and actionable biomarkers.","timeframe":"During initial diagnostic work-up"},{"test":"PET-CT and invasive mediastinal staging when indicated","clinical_question":"Is curative-intent treatment plausible and do mediastinal nodes require pathological confirmation?","expected_finding":"Offer PET-CT before curative-intent treatment and use EBUS-TBNA, EUS-FNA or surgical staging according to nodal size, PET uptake and whether results would change treatment.","decision_rationale":"Accurate nodal and distant staging prevents futile treatment and supports definitive planning.","timeframe":"Before definitive curative-intent treatment"}],"evidence":{"sources":[{"id":"360ba064-3f7b-4ec4-9948-1aa6fcde66b7","title":"Lung cancer: diagnosis and management","issuer":"NICE","edition":"NG122, published 28 March 2019; updated 8 March 2024","url":"https://www.nice.org.uk/guidance/ng122/chapter/Diagnosis-and-staging","locator":"Diagnosis and staging recommendations 1.2.1 to 1.2.27, including CT, tissue sampling, PET-CT and mediastinal staging","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed lung cancer; this limited extraction covers diagnostic imaging, tissue acquisition, molecular-pathology adequacy and staging before treatment selection."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Plan the diagnostic sequence to maximise combined diagnosis and staging information while minimising risk and delay, and avoid a biopsy target that provides less staging information when a more informative target is available.","timeframe":"At multidisciplinary diagnostic planning"},{"instruction":"Review confirmed lung cancer in a specialist multidisciplinary team with imaging, pathology, performance status, comorbidity, pulmonary reserve and patient preferences available before treatment selection.","timeframe":"Before definitive treatment"},{"instruction":"Review gaps: The NICE staging recommendations cite AJCC TNM seventh edition and therefore require reconciliation with the current TNM edition, Saudi oncology standards and local multidisciplinary pathways. This extraction does not verify surgery, radiotherapy or systemic anticancer drug regimens. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"360ba064-3f7b-4ec4-9948-1aa6fcde66b7","title":"Lung cancer: diagnosis and management","issuer":"NICE","edition":"NG122, published 28 March 2019; updated 8 March 2024","url":"https://www.nice.org.uk/guidance/ng122/chapter/Diagnosis-and-staging","locator":"Diagnosis and staging recommendations 1.2.1 to 1.2.27, including CT, tissue sampling, PET-CT and mediastinal staging","primary_source":true}],"selection_rationale":"Unverified scope: Adults with suspected or confirmed lung cancer; this limited extraction covers diagnostic imaging, tissue acquisition, molecular-pathology adequacy and staging before treatment selection."}}]},"nonClinicalManagement":{"patientEducation":["Explain histology, stage, biomarker results, treatment intent and realistic benefits and harms.","Provide urgent warning signs for haemoptysis, neurological change, cord compression and treatment toxicity.","Offer shared decision support that includes supportive-care-only options when appropriate."],"lifestyleAndDiet":["Provide evidence-based tobacco-cessation treatment at every stage without making treatment conditional on cessation.","Assess weight loss and sarcopenia and provide early nutrition support.","Encourage pulmonary rehabilitation or activity adapted to symptoms and treatment."],"mdtReferrals":["Thoracic surgery, medical oncology, radiation oncology and respiratory medicine","Molecular pathology/genomics for eligible disease","Palliative care from diagnosis of advanced disease or high symptom burden","Dietitian, physiotherapy, psycho-oncology and smoking-cessation service"],"dischargeCriteria":["Diagnosis, stage, biomarkers and MDT treatment intent are documented.","Acute respiratory or metabolic complications are controlled.","The patient has named contacts, toxicity guidance and a scheduled treatment or surveillance visit."],"followUpPlan":"Use stage- and treatment-specific surveillance with symptom review and scheduled imaging under the thoracic MDT; monitor late pulmonary and treatment effects and re-biopsy or repeat molecular assessment when progression could alter therapy."}}},{"id":"0f7cd64a-5778-4674-a0e5-e20fa64dc6a2","title":"Malignant Bowel Obstruction Support","original_version_id":"0f7cd64a-5778-4674-a0e5-e20fa64dc6a2","expected_hash":"59794fc9d32c6e6355708ab471792e11","source_url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9046338/","source_title":"MASCC multidisciplinary evidence-based recommendations for the management of malignant bowel obstruction in advanced cancer","issuer":"Other","scope":"Adults with malignant bowel obstruction in advanced cancer; this limited extraction covers assessment, symptom support, decompression, nutrition and selection for procedural or surgical intervention.","content":{"id":"0f7cd64a-5778-4674-a0e5-e20fa64dc6a2","title":"Malignant Bowel Obstruction Support","specialty":"Palliative Medicine / General Surgery","authority":"Textbook","status":"draft","version":"official-extraction-2026-10-11-b006","lastReviewed":"2026-10-10","pillar":"Palliative Care","clinicalReviewStatus":"pending","pathophysiology":{"summary":"Tumour infiltration, adhesions, dysmotility, or extrinsic compression can impede bowel transit. Obstruction may be partial or complete and cause pain, vomiting, fluid loss, and distress; management should reflect anatomy and goals. This topic is educational and should be interpreted alongside current local pathways and patient-specific assessment.","keyMechanisms":["Tumour infiltration, adhesions, dysmotility, or extrinsic compression can impede bowel transit. Obstruction may be partial or complete and cause pain, vomiting, fluid loss, and distress","management should reflect anatomy and goals."]},"presentation":{"symptoms":["Evaluate the characteristic symptom pattern of Malignant Bowel Obstruction Support, including onset, evolution, severity, associated symptoms, precipitating factors, complications, and relevant negative findings.","Clarify onset, progression, associated symptoms, baseline function, medicines and the patient’s own priorities.","Ask about relevant risk factors and context described in the case; document important negative findings rather than assuming their absence."],"physicalSigns":["Record observations and a focused examination directed to the organ system and competing diagnoses in this topic.","Assess functional change, comorbidity, hydration/perfusion where relevant, and baseline status.","Use serial reassessment when the condition or treatment can change over hours or days."],"redFlags":["Peritonitis, perforation, or sepsis","Uncontrolled vomiting or severe dehydration","Ischaemia or rapidly worsening pain","Inability to manage symptoms in current setting"]},"differentials":[{"condition":"Constipation/fecal impaction","distinguishingFeatures":"May mimic or contribute to obstruction."},{"condition":"Medication-related ileus","distinguishingFeatures":"Review opioids and anticholinergic burden."},{"condition":"Infectious or metabolic nausea","distinguishingFeatures":"Can coexist and may be reversible."}],"investigations":{"ruleIn":[{"tier":"laboratory","testName":"Focused history, abdominal examination, medication and bowel review, renal/electrolyte profile; imaging when it will clarify a management choice.","modalityTarget":"Focused history, abdominal examination, medication and bowel review, renal/electrolyte profile; imaging when it will clarify a management choice. — Malignant Bowel Obstruction Support","targetCondition":"Malignant Bowel Obstruction Support","expectedFinding":"A result that supports the working diagnosis or defines its severity, interpreted with the clinical picture and current criteria.","clinicalRationale":"Choose this investigation because it can confirm the suspected process, establish baseline risk, or change the next decision in this case."},{"tier":"specializedAdjunctive","testName":"Discuss surgical, endoscopic, decompressive, and comfort options with specialist team and patient.","modalityTarget":"Discuss surgical, endoscopic, decompressive, and comfort options with specialist team and patient. — Cause, complication, or risk relevant to Malignant Bowel Obstruction Support","targetCondition":"Cause, complication, or risk relevant to Malignant Bowel Obstruction Support","expectedFinding":"A result that may identify a precipitating factor or complication; interpret in context rather than as a stand-alone diagnosis.","clinicalRationale":"This helps detect an important alternative or complication and informs safe monitoring and referral."}],"ruleOut":[{"tier":"laboratory","testName":"Focused evaluation for the leading alternative diagnoses","modalityTarget":"Focused evaluation for the leading alternative diagnoses — Important alternative to Malignant Bowel Obstruction Support","targetCondition":"Important alternative to Malignant Bowel Obstruction Support","expectedFinding":"Findings that lower the likelihood of the selected alternative; a normal result does not exclude every urgent cause.","clinicalRationale":"The differential matters because it changes urgency or treatment and should be actively considered."},{"tier":"laboratory","testName":"Serial clinical reassessment with targeted repeat testing when indicated","modalityTarget":"Serial clinical reassessment with targeted repeat testing when indicated — Progression or evolving complication","targetCondition":"Progression or evolving complication","expectedFinding":"Stable or improving clinical trend without new evidence of the suspected complication.","clinicalRationale":"A single early assessment may miss an evolving problem; repeat only when it can guide care."}]},"clinicalManagement":[{"id":"assess-and-triage","title":"Assess urgency, stability, and the person’s priorities","timeframe":"At first contact and whenever the situation changes","actions":["Confirm the presenting concern, relevant timeline, baseline function, medicines, allergies, comorbidities, and the patient’s immediate priorities.","Assess the red flags above and use the current local escalation pathway if instability or rapid deterioration is present.","Explain uncertainty and involve the patient or appropriate decision-maker in a way suited to the setting."],"branches":[{"condition":"A red flag, instability, or rapid deterioration is present","actions":["Escalate immediately to the responsible senior or emergency team using the local pathway.","Stabilise and investigate in parallel; do not delay time-critical action for routine testing."]},{"condition":"The person is stable for a planned or longitudinal pathway","actions":["Proceed with focused assessment and shared planning.","Document the threshold for urgent reassessment."]}]},{"id":"confirm-and-stratify","title":"Confirm the working diagnosis and stratify risk","timeframe":"Promptly; adapt timing to acuity","actions":["Use the history, examination, and investigations listed above to confirm the likely process and assess important alternatives.","Interpret results using current national/local diagnostic criteria, age, pregnancy status, comorbidity, and prior results.","Record severity, uncertainty, and which findings would change the plan."],"branches":[{"condition":"The diagnosis remains uncertain or tests conflict with the clinical picture","actions":["Reassess the history and examination and seek senior or specialty advice.","Use targeted additional testing only when its result can change management."]},{"condition":"A high-risk complication or an alternative diagnosis is identified","actions":["Switch to the relevant urgent or specialty pathway.","Communicate the finding and handover responsibility clearly."]}]},{"id":"individualised-care","title":"Agree evidence-informed care and address the cause","timeframe":"According to acuity and current local protocol","actions":["Use the topic-specific focus in this record to agree immediate and longer-term priorities with the patient.","Select treatment only after checking current local guidance, formulary, contraindications, interactions, organ function, pregnancy considerations, and patient preference.","Treat reversible contributors and address access, communication, cultural, and functional barriers."],"branches":[{"condition":"Treatment is ineffective, poorly tolerated, or inconsistent with the patient’s goals","actions":["Reassess diagnosis, treatment burden, adherence barriers, and alternatives with the responsible specialist.","Document the shared decision and safety-net plan."]},{"condition":"The patient improves on the agreed plan","actions":["Continue the plan with monitoring proportional to risk.","Provide clear instructions for expected course and warning symptoms."]}]},{"id":"coordinate-and-follow-up","title":"Coordinate handover, education, and follow-up","timeframe":"Before transition and at the agreed review interval","actions":["Provide a written plan stating the working diagnosis, key findings, medicines or interventions, monitoring, and who owns each next step.","Use teach-back to check that the patient or caregiver understands warning symptoms, follow-up, and how to obtain help.","Close the loop on pending results, referrals, and screening or prevention actions."],"branches":[{"condition":"Safe care cannot be delivered in the current setting","actions":["Arrange a higher level of care or supported transfer and send a structured clinical handover.","Confirm transport, caregiver, and communication needs where relevant."]},{"condition":"The patient is ready for outpatient or continuing care","actions":["Confirm a feasible follow-up date and contact route.","Document when and how the plan should be reviewed or escalated."]}]}],"medicationPlan":{"status":"local-protocol-required","regimens":[],"note":"UNVERIFIED DRAFT — not approved for clinical use. Adults with malignant bowel obstruction in advanced cancer; this limited extraction covers assessment, symptom support, decompression, nutrition and selection for procedural or surgical intervention. The guideline names octreotide, lanreotide, metoclopramide and dexamethasone and gives a dexamethasone dose range of 4 to 16 mg daily with discontinuation after 3 to 5 days if ineffective, but does not supply a complete route, frequency, interaction and contraindication set for an exact regimen. No medicine regimen is encoded. Decisions require current local oncology, surgical, palliative and pharmacy review. Existing inherited sections are not newly verified. Existing sections outside this extraction are inherited unchanged and are not newly verified."},"granularPathway":{"schema_version":1,"evidence":{"sources":[{"id":"654d2ca9-5ed6-44cf-a78a-95c4bdc9b744","title":"MASCC multidisciplinary evidence-based recommendations for the management of malignant bowel obstruction in advanced cancer","issuer":"Other","edition":"MASCC guideline, published 5 May 2022","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9046338/","locator":"Table 3 and sections on antiemetics, corticosteroids, decompression, nutrition, hydration and surgery","primary_source":true}],"selection_rationale":"Unverified scope: Adults with malignant bowel obstruction in advanced cancer; this limited extraction covers assessment, symptom support, decompression, nutrition and selection for procedural or surgical intervention."},"Investigations":[{"id":"official-assessment","title":"Source-backed assessment draft","timeframe":"According to each source step","steps":[{"test":"Clinical and imaging confirmation of obstruction","clinical_question":"Is obstruction partial or complete, single-level or multi-level, and is a reversible or emergent surgical cause present?","expected_finding":"Assess symptoms, hydration, performance status, prognosis, cancer extent and imaging-defined obstruction before selecting supportive, endoscopic or surgical management.","decision_rationale":"Completeness, level, disease burden and goals determine whether prokinetic treatment, decompression, stenting or surgery is appropriate.","timeframe":"At presentation and with clinical deterioration"},{"test":"Symptom, hydration and nutrition assessment","clinical_question":"What are the burdens of nausea, vomiting, pain, distension, dehydration and inability to eat or drink?","expected_finding":"Assess symptoms and nutritional status individually and align hydration or nutrition interventions with prognosis, expected benefit, burdens and goals of care.","decision_rationale":"Routine artificial hydration or nutrition may not improve outcomes and can cause complications, especially near end of life.","timeframe":"At admission and repeatedly during supportive care"},{"test":"Suitability for decompression, stent or surgery","clinical_question":"Would nasogastric decompression, venting gastrostomy, self-expanding metal stent or surgery provide net benefit?","expected_finding":"Use temporary nasogastric decompression for acute obstruction, consider venting gastrostomy for longer-term decompression, prefer a stent for suitable single-level large-bowel obstruction, and reserve surgery for highly selected patients.","decision_rationale":"Interventions differ in invasiveness, durability, complication risk and likely benefit.","timeframe":"Early multidisciplinary review after initial stabilisation"}],"evidence":{"sources":[{"id":"654d2ca9-5ed6-44cf-a78a-95c4bdc9b744","title":"MASCC multidisciplinary evidence-based recommendations for the management of malignant bowel obstruction in advanced cancer","issuer":"Other","edition":"MASCC guideline, published 5 May 2022","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9046338/","locator":"Table 3 and sections on antiemetics, corticosteroids, decompression, nutrition, hydration and surgery","primary_source":true}],"selection_rationale":"Unverified scope: Adults with malignant bowel obstruction in advanced cancer; this limited extraction covers assessment, symptom support, decompression, nutrition and selection for procedural or surgical intervention."}}],"Treatment_Plan":[{"id":"official-management","title":"Limited source-backed management draft","timeframe":"According to each source action","actions":[{"instruction":"Keep the person nil by mouth initially, provide symptom-led decompression and supportive care, then reintroduce oral intake gradually when obstruction improves and symptoms permit.","timeframe":"During the acute episode and recovery"},{"instruction":"Avoid metoclopramide in complete malignant bowel obstruction because of possible perforation risk; somatostatin analogues may reduce vomiting, and corticosteroids may offer short-term symptom benefit only after local medicine review.","timeframe":"During medication selection"},{"instruction":"Use parenteral hydration or nutrition only in selected people when expected benefit outweighs burden; do not initiate these routinely at the end of life.","timeframe":"At goals-of-care and nutrition review"},{"instruction":"Review gaps: The guideline names octreotide, lanreotide, metoclopramide and dexamethasone and gives a dexamethasone dose range of 4 to 16 mg daily with discontinuation after 3 to 5 days if ineffective, but does not supply a complete route, frequency, interaction and contraindication set for an exact regimen. No medicine regimen is encoded. Decisions require current local oncology, surgical, palliative and pharmacy review. Existing inherited sections are not newly verified.","timeframe":"Before clinical approval"}],"Medicines_Doses":[],"branches":[],"evidence":{"sources":[{"id":"654d2ca9-5ed6-44cf-a78a-95c4bdc9b744","title":"MASCC multidisciplinary evidence-based recommendations for the management of malignant bowel obstruction in advanced cancer","issuer":"Other","edition":"MASCC guideline, published 5 May 2022","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9046338/","locator":"Table 3 and sections on antiemetics, corticosteroids, decompression, nutrition, hydration and surgery","primary_source":true}],"selection_rationale":"Unverified scope: Adults with malignant bowel obstruction in advanced cancer; this limited extraction covers assessment, symptom support, decompression, nutrition and selection for procedural or surgical intervention."}}]},"nonClinicalManagement":{"patientEducation":["Explain malignant bowel obstruction support in plain language, including what is known, what remains uncertain, and how the plan will be reviewed.","Use teach-back for warning signs, medicines or monitoring, and the route to urgent help.","Invite questions and adapt written or interpreted information to the patient’s language, health literacy, and communication needs."],"lifestyleAndDiet":["Offer topic-relevant prevention or self-management support that is safe, feasible, culturally appropriate, and consistent with the person’s goals.","Avoid one-size-fits-all restrictions; individualise advice for pregnancy, frailty, kidney/heart disease, disability, and treatment burden."],"mdtReferrals":["Palliative Medicine / General Surgery","Primary care or the responsible continuity team","Pharmacist, nurse educator, dietitian, rehabilitation, mental-health, or social support when relevant to the case."],"dischargeCriteria":["Clinical status is appropriate for the next setting, and urgent complications have been excluded or addressed.","The patient or caregiver has an understandable plan, access to needed treatment/support, and a clear escalation route.","Pending investigations and referrals have a named owner and follow-up timeframe."],"followUpPlan":"Review the topic-specific focus, patient goals, symptoms and function at an interval matched to risk. Reconcile new results and treatment effects, close referrals, and revisit the plan if the condition, circumstances, or preferences change."}}}]$population$)
